// Elementor AI's image panel, the 'Generate images' slide-over inside the Elementor editor (WordPress), in a June 2023 tutorial
// screen recording (YouTube tU6mOwGZa44, 2023-06-22, t=181.0-187.0 s; the same panel and CTA in 3oE18jc5ryA, 2023-10-16, where the
// wait itself is not on screen; spec .tmp/clone-9e82faf1/reveal-refs/elementor-ai/spec.json, confidence 0.6; frames ba_el_t180.5,
// ba_el_t181.5-ba_el_t186.5, ba_el_t187.5, ba_el_wait_full). A white sheet in two columns: on the left the bold heading
// 'Imagine anything / create everything', the helper line, the prompt box, the Image type / Style / Aspect ratio selects
// ('Background', 'Floral', 'Landscape (16:9)' in the press frames) and a full-width CTA, 'Generate images'; on the right the results field, which before the press carries
// the line 'Spark your imagination with images generated by our community' over a grid of the community's pictures. Pressing the
// CTA removes that grid and the field goes blank white: centred in it, a small black four-point sparkle (one large outlined star
// with two small solid ones at its upper and lower right), the bold line 'Bringing your vision to life...', the lighter line
// 'Hold tight, painting dreams might take a moment.' and a thin bar that fills beneath them. The prompt and the selects grey out
// and the CTA turns pale grey while it runs; then the results grid appears as blank light-grey cells (#F2F2F2), the CTA is the
// dark 'Generate again' (with a 'New prompt' link under it) and the pictures fill the cells.
// Adapted to ten images: four columns, 4 + 4 + 2 square cells filling in strict reading order (the footage's grid holds four,
// two to a row, and scrolls). The bar is computed from t, fills left to right over the wait and is frozen at the last landing.
// Omitted: the WordPress admin bar, the Elementor 'AI' wordmark with its 'Beta' chip, the 'Upgrade' chip and the close button,
// and the browser frame and the creator's banner. The footage's pictures are never reproduced: every cell is our own meme.
import { seg, press } from '../../../../lib.9b47fc30.js';
import { injectStyle, restTransform, restFilter, ownSrc, UI_FONT } from './util.9e82faf1.js';

const P = 'rv-ela';
const ROOT_H = 372, LEFT_W = 188, COLS = 4, GAP = 6;
const CSS = `
.${P} { box-sizing: border-box; display: flex; width: 560px; max-width: 100%; height: ${ROOT_H}px; border-radius: 12px; background: #fff; color: #0b0b0b; font-family: ${UI_FONT}; -webkit-font-smoothing: antialiased; overflow: hidden; box-shadow: 0 0 0 1px #e2e2e2; }
.${P}-l { flex: none; box-sizing: border-box; display: flex; flex-direction: column; width: ${LEFT_W}px; padding: 14px; border-right: 1px solid #e6e6e6; }
.${P}-h { flex: none; font-size: 17px; line-height: 20px; font-weight: 700; letter-spacing: -.01em; color: #0b0b0b; }
.${P}-sub { flex: none; margin-top: 6px; font-size: 8.5px; line-height: 12px; color: #3f4448; }
.${P}-pr { position: relative; flex: none; box-sizing: border-box; height: 54px; margin-top: 10px; padding: 6px 8px; border: 1px solid #cfcfcf; border-radius: 3px; font-size: 8.5px; line-height: 12px; color: #1a1a1a; overflow: hidden; }
.${P}-pr svg { position: absolute; right: 5px; bottom: 4px; width: 10px; height: 10px; fill: none; stroke: #8c9196; stroke-width: 1.3; stroke-linecap: round; stroke-linejoin: round; }
.${P}-sel { position: relative; flex: none; box-sizing: border-box; display: flex; align-items: center; height: 24px; margin-top: 11px; padding: 0 8px; border: 1px solid #c9c9c9; border-radius: 3px; font-size: 8.5px; color: #1a1a1a; white-space: nowrap; }
.${P}-sel small { position: absolute; left: 6px; top: -5px; padding: 0 2px; background: #fff; font-size: 6.5px; line-height: 9px; color: #4a4f53; }
.${P}-sel svg { position: absolute; right: 7px; top: 8px; width: 7px; height: 7px; fill: none; stroke: #1a1a1a; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.${P}-foot { margin-top: auto; flex: none; }
.${P}-cta { display: flex; align-items: center; justify-content: center; gap: 6px; box-sizing: border-box; height: 32px; border-radius: 2px; background: #f0bafb; font-size: 9.5px; font-weight: 600; color: #141414; white-space: nowrap; }
.${P}-cta svg { flex: none; width: 9px; height: 9px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.${P}-cta .${P}-ic2 { display: none; }
.${P}-np { height: 22px; font-size: 8.5px; line-height: 22px; text-align: center; color: #3f4448; visibility: hidden; }
.${P}-r { position: relative; flex: 1; min-width: 0; display: flex; align-items: center; justify-content: center; background: #fff; overflow: hidden; }
.${P}-idle { position: absolute; left: 0; right: 0; top: 0; bottom: 0; box-sizing: border-box; padding: 14px 16px; }
.${P}-cap { height: 12px; margin-bottom: 8px; font-size: 9px; line-height: 12px; font-weight: 600; color: #1a1a1a; white-space: nowrap; }
.${P}-cg, .${P}-g { display: grid; grid-template-columns: repeat(${COLS}, minmax(0, 1fr)); gap: ${GAP}px; }
.${P}-cg i { display: block; aspect-ratio: 1; background: #eef0f1; }
.${P}-wait { position: absolute; left: 0; right: 0; top: 0; bottom: 0; display: none; flex-direction: column; align-items: center; justify-content: center; background: #fff; }
.${P}-spk { display: block; width: 24px; height: 28px; }
.${P}-bt { margin-top: 12px; font-size: 11.5px; line-height: 15px; font-weight: 700; color: #0b0b0b; white-space: nowrap; }
.${P}-st { margin-top: 9px; font-size: 8.5px; line-height: 12px; color: #3a3a3a; white-space: nowrap; }
.${P}-bar { position: relative; width: 68%; height: 3px; margin-top: 22px; background: #b3b3b3; }
.${P}-bar u { position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: #3c3c3c; }
.${P}-g { flex: none; box-sizing: border-box; width: 100%; padding: 0 16px; }
.${P}-t { position: relative; aspect-ratio: 1; overflow: hidden; background: #f2f2f2; }
.${P}-z { position: absolute; left: 0; right: 0; top: 0; bottom: 0; }
.${P}-t img { position: absolute; left: 0; top: 0; display: block; width: 100%; height: 100%; object-fit: cover; }
.${P}-cv { position: absolute; left: 0; right: 0; top: 0; bottom: 0; background: #f2f2f2; }
.${P}-s1 .${P}-pr, .${P}-s1 .${P}-sel { color: #cccccc; }
.${P}-s1 .${P}-sel { border-color: #dcdcdc; }
.${P}-s1 .${P}-sel svg { stroke: #bdbdbd; }
.${P}-s1 .${P}-pr svg { stroke: #cccccc; }
.${P}-s1 .${P}-cta { background: #e0e0e0; color: #9a9a9a; }
.${P}-s2 .${P}-cta { background: #393f45; color: #fff; }
.${P}-s2 .${P}-ic1 { display: none; }
.${P}-s2 .${P}-ic2 { display: block; }
.${P}-s2 .${P}-np { visibility: visible; }
`;

const PROMPT = 'A muse holding up a handwritten note in a lecture hall, meme style, bright colours';
const REF = 1.84;                                 // the beat in seconds from the card's entrance: cardIn .. lastLand, stretched with the real window
const GEN_AT = 0.06;                              // the cursor presses 'Generate images'
const ISSUE = 0.14;                               // the community grid goes and the results field blanks to the sparkle caption
const GRID_AT = 0.80;                             // the bar is full: the blank cells appear and the CTA reads 'Generate again'
const LAND = Array.from({ length: 10 }, (_, i) => 0.92 + i * 0.078);   // cell i takes its picture (strict reading order), the last at 1.622
const FADE = 0.05;                                // a cell's grey cover thins away over this long before the picture lands
const CELLS = ['#e9eef0', '#f1ece8', '#e8edf2', '#eef1e9', '#f0e9ee', '#e9f0ee', '#f2eee7', '#e8ebf1', '#f0eaea', '#ebf0ec', '#eeeaf2', '#f1f0e8'];
const SPARK = `<svg class="${P}-spk" viewBox="0 0 24 28"><path d="M10.5 4C11.3 10.5 14 13.2 20.5 14C14 14.8 11.3 17.5 10.5 24C9.7 17.5 7 14.8 0.5 14C7 13.2 9.7 10.5 10.5 4Z" fill="none" stroke="#000" stroke-width="2.2" stroke-linejoin="round"/><path d="M20 0.6C20.5 3 21 3.7 23.4 4.2C21 4.7 20.5 5.4 20 7.8C19.5 5.4 19 4.7 16.6 4.2C19 3.7 19.5 3 20 0.6Z" fill="#000"/><path d="M20 20.2C20.5 22.6 21 23.3 23.4 23.8C21 24.3 20.5 25 20 27.4C19.5 25 19 24.3 16.6 23.8C19 23.3 19.5 22.6 20 20.2Z" fill="#000"/></svg>`;
const CHEV = '<svg viewBox="0 0 12 12"><path d="M2.5 4.5l3.5 3.5 3.5-3.5"/></svg>';
const WAND = '<svg viewBox="0 0 12 12"><path d="M2 10l6-6M7 2.2l.6 1.3 1.3.6-1.3.6L7 6l-.6-1.3-1.3-.6 1.3-.6zM9.5 6.5l.4.8.8.4-.8.4-.4.8-.4-.8-.8-.4.8-.4z"/></svg>';
const STAR = '<svg class="' + P + '-ic1" viewBox="0 0 12 12"><path d="M5 1.5c.4 2.6 1 3.2 3.6 3.6C6 5.5 5.4 6.1 5 8.7 4.6 6.1 4 5.5 1.4 5.1 4 4.7 4.6 4.1 5 1.5zM9.4 7.2c.2 1.1.5 1.4 1.6 1.6-1.1.2-1.4.5-1.6 1.6-.2-1.1-.5-1.4-1.6-1.6 1.1-.2 1.4-.5 1.6-1.6z"/></svg>';
const REDO = '<svg class="' + P + '-ic2" viewBox="0 0 12 12"><path d="M10 5.2A4.2 4.2 0 0 0 2.4 3.6M2 6.8a4.2 4.2 0 0 0 7.6 1.6M2.2 1.6v2.2h2.2M9.8 10.4V8.2H7.6"/></svg>';

export default {
  id: 'elementor-ai',
  label: 'Elementor AI images (2023)',
  source: {
    platform: "Elementor AI image panel inside the Elementor editor (WordPress), the 'Generate images' slide-over (desktop browser, light theme; tutorial screen recordings on YouTube: tU6mOwGZa44, 2023-06-22, t=181.0-187.0 s; 3oE18jc5ryA, 2023-10-16)",
    feature: "white two-column panel: heading 'Imagine anything / create everything', the Image type ('Background') / Style ('Floral') / Aspect ratio ('Landscape (16:9)') selects and a CTA; pressing 'Generate images' removes the community grid, the results field blanks and centres a black four-point sparkle, 'Bringing your vision to life...', 'Hold tight, painting dreams might take a moment.' and a thin bar filling beneath them, the CTA turns grey and then reads 'Generate again'; the blank cells then fill with the pictures (adapted to 10: a 4 + 4 + 2 block of square cells in reading order; the admin bar, the AI Beta and Upgrade chips and the browser frame are omitted)",
    refs: [
      { url: 'https://www.youtube.com/watch?v=tU6mOwGZa44', id: 'tU6mOwGZa44', published: '2023-06-22', retrieved: '2026-10-15', note: 'the wait on screen, t=181.0-187.0 s' },
      { url: 'https://www.youtube.com/watch?v=3oE18jc5ryA', id: '3oE18jc5ryA', published: '2023-10-16', retrieved: '2026-10-15', note: "the same panel and CTA; the blanked results area is not captured" },
    ],
    extrapolated: [
      "ten square cells in a 4 + 4 + 2 block, all in view with no scroll: the footage's grid holds four (two to a row, landscape pictures in letterboxed grey cells) and scrolls",
      "the cell order and timing of the landings: the footage shows four blank cells ('generated-0'..'generated-3' as alt text) and then four pictures at once, never one by one; the alt labels are not drawn",
      "the bar's progress: it fills from empty to full over the wait, left to right and linear in t; the footage's bar changes between frames only as a dark segment against a lighter track, so whether it is determinate or a sweep is unsettled (spec unknowns)",
      "the community grid before the press: plain tinted cells and the caption 'Spark your imagination with images generated by our community'; no frame shows it (t=180.5 is already the press)",
      "the result cells are square although the Aspect ratio row reads 'Landscape (16:9)' (the footage's pictures are landscape in square-ish grey cells): ours are our own square memes",
      "the pending field is white, not the spec's #F2F2F2: the frames sample #FFFFFF around the glyph and #F2F2F2 only on the empty result cells",
      "the prompt text and the cell layout: our own; the 'New prompt' link under 'Generate again' is the footage's (t=184.5 on)",
    ],
  },
  build(x, ctx) {
    injectStyle(P, CSS);
    const { tiles } = ctx;
    const src = ownSrc(ctx.src, 'elementor-ai');
    const cell = (g, i) => `<div class="${P}-t"><div class="${P}-z" style="transform-origin: ${g.origin}; transform: ${restTransform(g)}"><img src="${src}" width="870" height="1024" decoding="sync" alt="Muse meme ${i + 1}" style="visibility: hidden; filter: ${restFilter(g)}"/><div class="${P}-cv"></div></div></div>`;
    const sel = (lab, v) => `<div class="${P}-sel"><small>${lab}</small>${v}${CHEV}</div>`;
    const root = x.el(`<div class="${P}"><div class="${P}-l"><div class="${P}-h">Imagine anything<br>create everything</div><div class="${P}-sub">Generate images by selecting the desired type and style, and entering a prompt.</div><div class="${P}-pr">${x.esc(PROMPT)}${WAND}</div>${sel('Image type', 'Background')}${sel('Style', 'Floral')}${sel('Aspect ratio', 'Landscape (16:9)')}<div class="${P}-foot"><div class="${P}-cta">${STAR}${REDO}<span>Generate images</span></div><div class="${P}-np">New prompt</div></div></div><div class="${P}-r"><div class="${P}-idle"><div class="${P}-cap">Spark your imagination with images generated by our community</div><div class="${P}-cg">${CELLS.map((c) => `<i style="background: ${c}"></i>`).join('')}</div></div><div class="${P}-wait">${SPARK}<div class="${P}-bt">Bringing your vision to life...</div><div class="${P}-st">Hold tight, painting dreams might take a moment.</div><div class="${P}-bar"><u></u></div></div><div class="${P}-g" style="visibility: hidden">${tiles.map(cell).join('')}</div></div></div>`);
    const cta = root.querySelector(`.${P}-cta`), label = cta.querySelector('span'), idle = root.querySelector(`.${P}-idle`), wait = root.querySelector(`.${P}-wait`), fill = root.querySelector(`.${P}-bar u`), grid = root.querySelector(`.${P}-g`);
    const cells = [...root.querySelectorAll(`.${P}-t`)].map((n) => ({ im: n.querySelector('img'), cv: n.querySelector(`.${P}-cv`) }));
    ctx.gate(cells.map((c) => c.im));

    // memoised writes: the DOM is set from t alone, so a seek lands on the same state whatever came before
    const memo = new Map();
    const put = (key, v, fn) => { if (memo.get(key) !== v) { memo.set(key, v); fn(v); } };

    return {
      root,
      render(t) {
        const k = (ctx.lastLand - ctx.cardIn) / REF;   // the beat's window against the layout above
        const s = (t - ctx.cardIn) / k;                // layout seconds since the card entered
        const te = Math.min(s, LAND[9]);               // the wait's clock stops at the last landing: the bar holds there

        // the CTA is pressed, greys out while the run is on, then reads 'Generate again'
        const gp = press(s, GEN_AT, 0.06, 0.06, 0.14);
        put('go', gp.toFixed(3), () => { cta.style.transform = gp > 0 ? `scale(${(1 - 0.03 * gp).toFixed(4)})` : 'none'; });
        const stage = s < ISSUE ? 0 : s < GRID_AT ? 1 : 2;
        put('stage', stage, (v) => { root.className = `${P} ${P}-s${v}`; label.textContent = v === 2 ? 'Generate again' : 'Generate images'; });

        // the community grid gives way to the blank field with the sparkle caption, then to the results cells
        put('idle', stage === 0, (v) => { idle.style.display = v ? '' : 'none'; });
        put('wait', stage === 1, (v) => { wait.style.display = v ? 'flex' : 'none'; });
        put('grid', stage === 2, (v) => { grid.style.visibility = v ? '' : 'hidden'; });

        // the bar fills left to right over the wait, from t alone
        const bar = seg(te, ISSUE, GRID_AT);
        put('bar', bar.toFixed(4), () => { fill.style.width = `${(bar * 100).toFixed(2)}%`; });

        cells.forEach((c, i) => {
          const a = LAND[i];
          const f = seg(s, a - FADE, a);
          put(`i${i}`, s >= a - FADE, (v) => { c.im.style.visibility = v ? '' : 'hidden'; });
          put(`c${i}`, f.toFixed(3), () => {
            if (f >= 1) { c.cv.style.display = 'none'; c.cv.style.opacity = ''; } else { c.cv.style.display = ''; c.cv.style.opacity = f > 0 ? (1 - f).toFixed(3) : ''; }
          });
        });
      },
    };
  },
};
